impl Document {
    pub(crate) fn compare_ar_parameter_in_implementation_data_instance_ref(
        &self,
        _other: &Document,
        a: &ArParameterInImplementationDataInstanceRef,
        b: &ArParameterInImplementationDataInstanceRef,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        Ok(())
    }

    pub(crate) fn compare_ar_variable_in_implementation_data_instance_ref(
        &self,
        _other: &Document,
        a: &ArVariableInImplementationDataInstanceRef,
        b: &ArVariableInImplementationDataInstanceRef,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        let list_a = a.get_context_data_prototype_refs();
        let list_b = b.get_context_data_prototype_refs();
        if list_a.len() != list_b.len() {
            return Err(format!(
                "{path}: CONTEXT_DATA_PROTOTYPE_REFS length mismatch"
            ));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            if x != y {
                return Err(format!(
                    "{path}.CONTEXT_DATA_PROTOTYPE_REFS[{index}] mismatch"
                ));
            }
        }
        if a.get_port_prototype_ref() != b.get_port_prototype_ref() {
            return Err(format!("{path}: PORT_PROTOTYPE_REF mismatch"));
        }
        if a.get_root_variable_data_prototype_ref() != b.get_root_variable_data_prototype_ref() {
            return Err(format!("{path}: ROOT_VARIABLE_DATA_PROTOTYPE_REF mismatch"));
        }
        if a.get_target_data_prototype_ref() != b.get_target_data_prototype_ref() {
            return Err(format!("{path}: TARGET_DATA_PROTOTYPE_REF mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_autosar_parameter_ref(
        &self,
        _other: &Document,
        a: &AutosarParameterRef,
        b: &AutosarParameterRef,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        if a.get_autosar_parameter_i_ref() != b.get_autosar_parameter_i_ref() {
            return Err(format!("{path}: AUTOSAR_PARAMETER_I_REF mismatch"));
        }
        if a.get_local_parameter_ref() != b.get_local_parameter_ref() {
            return Err(format!("{path}: LOCAL_PARAMETER_REF mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_autosar_variable_ref(
        &self,
        _other: &Document,
        a: &AutosarVariableRef,
        b: &AutosarVariableRef,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        if a.get_autosar_variable_i_ref() != b.get_autosar_variable_i_ref() {
            return Err(format!("{path}: AUTOSAR_VARIABLE_I_REF mismatch"));
        }
        if a.get_autosar_variable_in_impl_datatype() != b.get_autosar_variable_in_impl_datatype() {
            return Err(format!(
                "{path}: AUTOSAR_VARIABLE_IN_IMPL_DATATYPE mismatch"
            ));
        }
        if a.get_local_variable_ref() != b.get_local_variable_ref() {
            return Err(format!("{path}: LOCAL_VARIABLE_REF mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_parameter_access(
        &self,
        other: &Document,
        a: &ParameterAccess,
        b: &ParameterAccess,
        path: &str,
    ) -> Result<(), String> {
        self.compare_abstract_access_point(other, a.base(), b.base(), path)?;
        self.compare_variation_point_capable(
            other,
            a.variation_point_capable(),
            b.variation_point_capable(),
            path,
        )?;
        if a.get_accessed_parameter() != b.get_accessed_parameter() {
            return Err(format!("{path}: ACCESSED_PARAMETER mismatch"));
        }
        if a.get_sw_data_def_props() != b.get_sw_data_def_props() {
            return Err(format!("{path}: SW_DATA_DEF_PROPS mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_variable_access(
        &self,
        other: &Document,
        a: &VariableAccess,
        b: &VariableAccess,
        path: &str,
    ) -> Result<(), String> {
        self.compare_abstract_access_point(other, a.base(), b.base(), path)?;
        self.compare_variation_point_capable(
            other,
            a.variation_point_capable(),
            b.variation_point_capable(),
            path,
        )?;
        if a.get_accessed_variable() != b.get_accessed_variable() {
            return Err(format!("{path}: ACCESSED_VARIABLE mismatch"));
        }
        if a.get_scope() != b.get_scope() {
            return Err(format!("{path}: SCOPE mismatch"));
        }
        Ok(())
    }
}
